import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

@SpringBootTest
class ContactViewTest extends SpringBrowserlessTest {

    @Test
    void headingAndAboutLinkPresent() {
        ContactView view = navigate(ContactView.class);
        assertEquals("Contact", $(H1.class).single().getText());
        RouterLink link = $(RouterLink.class).withText("About").single();
        assertTrue(link.getElement().getText().equals("About"));
    }

    @Test
    void sendIsEnabledOnEmptyForm() {
        navigate(ContactView.class);
        Button send = $(Button.class).withText("Send").single();
        assertTrue(send.isEnabled());
    }

    @Test
    void blankNameIsRejected() {
        navigate(ContactView.class);
        TextField name = $(TextField.class).withLabel("Name").single();
        EmailField email = $(EmailField.class).withLabel("Email").single();
        TextArea message = $(TextArea.class).withLabel("Message").single();

        test(email).setValue("a@b.com");
        test(message).setValue("hello");

        Button send = $(Button.class).withText("Send").single();
        test(send).click();

        assertTrue(name.isInvalid());
        assertEquals("Name is required", name.getErrorMessage());
    }

    @Test
    void invalidEmailIsRejected() {
        navigate(ContactView.class);
        TextField name = $(TextField.class).withLabel("Name").single();
        EmailField email = $(EmailField.class).withLabel("Email").single();
        TextArea message = $(TextArea.class).withLabel("Message").single();

        test(name).setValue("Jane");
        test(email).setValue("not-an-email");
        test(message).setValue("hello");

        Button send = $(Button.class).withText("Send").single();
        test(send).click();

        assertTrue(email.isInvalid());
        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
    }

    @Test
    void missingEmailAndPhoneIsRejected() {
